1	/**
2	 * SDK E2E Test Harness
3	 *
4	 * Creates authenticated CipherBoxClient instances backed by real API accounts.
5	 * Extracted from packages/sdk/src/__tests__/integration.test.ts pattern.
6	 *
7	 * Each call to createTestContext() creates a unique user via /auth/test-login,
8	 * initializes their vault, and returns a ready-to-use CipherBoxClient.
9	 */
10	
11	import {
12	  CipherBoxClient,
13	  buildGrantRemintCallbacks,
14	  type RotationClientCallbacks,
15	  type OwnerReconcileTransport,
16	  type GrantRow,
17	} from '@cipherbox/sdk';
18	import { initializeVault } from '@cipherbox/core';
19	import { hexToBytes, bytesToHex, base64ToBytes } from '@cipherbox/crypto';
20	import { publishVaultKeyBlob, publishEmptyRootNode } from '@cipherbox/sdk-core';
21	import type { SdkContext } from '@cipherbox/sdk-core';
22	import { createAxiosInstance } from '@cipherbox/api-client';
23	
24	const API_URL = process.env.SDK_E2E_API_URL ?? 'http://localhost:3000';
25	const SECRET = process.env.SDK_E2E_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
26	const THROTTLE_BYPASS = process.env.THROTTLE_BYPASS_SECRET ?? '';
27	
28	/**
29	 * Build default headers for fetch calls.
30	 * Includes the throttle bypass header when THROTTLE_BYPASS_SECRET is set.
31	 */
32	function fetchHeaders(extra: Record<string, string> = {}): Record<string, string> {
33	  const headers: Record<string, string> = { ...extra };
34	  if (THROTTLE_BYPASS) {
35	    headers['X-Throttle-Bypass'] = THROTTLE_BYPASS;
36	  }
37	  return headers;
38	}
39	
40	/** Default headers for the api-client axios instance (throttle bypass). */
41	function axiosDefaultHeaders(): Record<string, string> | undefined {
42	  return THROTTLE_BYPASS ? { 'X-Throttle-Bypass': THROTTLE_BYPASS } : undefined;
43	}
44	
45	/** Shape of a sent-share row (SentShareResponseDto) as returned by GET /shares/sent. */
46	interface SentShareRow {
47	  shareId: string;
48	  recipientPublicKey: string;
49	  encryptedReadKey: string;
50	  rootNodeId: string;
51	  shareRootIpnsName: string;
52	  rootGeneration: string;
53	}
54	
55	/**
56	 * Build the opt-in web-mirroring `rotationCallbacks` seam for a single account.
57	 *
58	 * Mirrors apps/web (`rotation-driver.service.ts` + `owner-reconcile.service.ts`)
59	 * but sources every grant op from THIS account's own API via `testFetch` +
60	 * `accessToken` (the api-client global singleton carries no per-account auth).
61	 *
62	 * `clientHolder` is late-bound: the callbacks only fire during later mutations,
63	 * so the CipherBoxClient is assigned into the holder AFTER construction.
64	 *
65	 * `resolveInlineGrantRemint` can be disabled at runtime via the
66	 * `E2E_DISABLE_INLINE_REMINT=1` env hook (defaults to enabled) — this lets the
67	 * suite prove the seam is a REAL gate by re-running with the seam removed and
68	 * confirming the re-mint assertion fails.
69	 */
70	function buildInlineGrantRemintCallbacks(
71	  apiUrl: string,
72	  accessToken: string,
73	  clientHolder: { client: CipherBoxClient | null }
74	): RotationClientCallbacks {
75	  const authHeaders = (extra: Record<string, string> = {}) =>
76	    fetchHeaders({ Authorization: `Bearer ${accessToken}`, ...extra });
77	
78	  async function fetchSentShares(): Promise<SentShareRow[]> {
79	    const res = await testFetch(`${apiUrl}/shares/sent`, { headers: authHeaders() });
80	    if (!res.ok) {
81	      throw new Error(`GET /shares/sent failed (${res.status}): ${await res.text()}`);
82	    }
83	    const data = (await res.json()) as { shares: SentShareRow[] };
84	    return data.shares;
85	  }
86	
87	  const listSentGrants = async (): Promise<GrantRow[]> => {
88	    const shares = await fetchSentShares();
89	    return shares.map((s) => ({
90	      shareId: s.shareId,
91	      recipientPublicKey: hexToBytes(
92	        s.recipientPublicKey.startsWith('0x') ? s.recipientPublicKey.slice(2) : s.recipientPublicKey
93	      ),
94	      isRevoked: false,
95	      rootNodeId: s.rootNodeId,
96	    }));
97	  };
98	
99	  const updateGrant = async (
100	    shareId: string,
101	    encryptedReadKey: string,
102	    generation: number
103	  ): Promise<void> => {
104	    // sdk-core `reMintGrantsRootedAt` hands `encryptedReadKey` as BASE64
105	    // (engine.ts:648 bytesToBase64), but PATCH /shares/:id/grant requires even-
106	    // length HEX (like the share-create DTO + the SDK's own share-create path).
107	    // This mismatch (a genuine product bug that also affects the web
108	    // owner-reconcile path) makes every re-mint PATCH 400. The `E2E_REMINT_HEX=1`
109	    // opt-in converts base64→hex so the file-share-rotation-remint reproduction
110	    // can reach the deeper file-key gap. It is a DIAGNOSTIC, not a fix, and
111	    // defaults OFF so the harness stays a faithful mirror of web.
112	    const encHex =
113	      process.env.E2E_REMINT_HEX === '1'
114	        ? bytesToHex(base64ToBytes(encryptedReadKey))
115	        : encryptedReadKey;
116	    const res = await testFetch(`${apiUrl}/shares/${shareId}/grant`, {
117	      method: 'PATCH',
118	      headers: authHeaders({ 'Content-Type': 'application/json' }),
119	      body: JSON.stringify({ encryptedReadKey: encHex, rootGeneration: String(generation) }),
120	    });
121	    if (!res.ok) {
122	      throw new Error(`PATCH /shares/${shareId}/grant failed (${res.status}): ${await res.text()}`);
123	    }
124	  };
125	
126	  const deleteGrant = async (shareId: string): Promise<void> => {
127	    const res = await testFetch(`${apiUrl}/shares/${shareId}`, {
128	      method: 'DELETE',
129	      headers: authHeaders(),
130	    });
131	    if (!res.ok && res.status !== 204) {
132	      throw new Error(`DELETE /shares/${shareId} failed (${res.status}): ${await res.text()}`);
133	    }
134	  };
135	
136	  return {
137	    getActiveGrantRootIpnsNames: async () => {
138	      const shares = await fetchSentShares();
139	      return new Set(shares.map((s) => s.shareRootIpnsName));
140	    },
141	    getLocalGrantRecord: () => null,
142	    persistJob: () => {},
143	    resolveInlineGrantRemint: async (_rootNodeIpnsName: string, _rootNodeId: string) => {
144	      const shares = await fetchSentShares();
145	      if (shares.length === 0) return undefined;
146	
147	      // nodeId -> shareRootIpnsName, so the per-node getRecipientPubkeyPins seam
148	      // resolves the right node's owner-sealed pins during the rotation walk.
149	      const nodeIdToIpnsName = new Map<string, string>();
150	      for (const s of shares) {
151	        if (!nodeIdToIpnsName.has(s.rootNodeId)) {
152	          nodeIdToIpnsName.set(s.rootNodeId, s.shareRootIpnsName);
153	        }
154	      }
155	
156	      const grants = await listSentGrants();
157	
158	      const transport: OwnerReconcileTransport = {
159	        listSentGrants,
160	        updateGrant,
161	        deleteGrant,
162	        getRecipientPubkeyPins: (nodeId: string) => {
163	          const ipnsName = nodeIdToIpnsName.get(nodeId);
164	          if (!ipnsName) {
165	            throw new Error(
166	              `resolveInlineGrantRemint: no share-root IPNS name for node ${nodeId} — refusing to re-mint (fail-closed)`
167	            );
168	          }
169	          const client = clientHolder.client;
170	          if (!client) throw new Error('resolveInlineGrantRemint: client not initialized');
171	          return client.getRecipientPubkeyPins(ipnsName);
172	        },
173	      };
174	
175	      return {
176	        innerGrants: grants,
177	        grantCallbacks: buildGrantRemintCallbacks(transport),
178	      };
179	    },
180	  };
181	}
182	
183	/** Core account data returned by createTestAccount (shared between sdk-e2e and load tests). */
184	export interface TestAccount {
185	  client: CipherBoxClient;
186	  accessToken: string;
187	  publicKey: Uint8Array;
188	  privateKey: Uint8Array;
189	  rootIpnsName: string;
190	  rootFolderKey: Uint8Array;
191	  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
192	  email: string;
193	  /**
194	   * UUID of the root Node published by publishEmptyRootNode (D-06). Threaded
195	   * into the client's folderTree via registerFolder so root-folder publishes
196	   * (e.g. uploadFile to the root) carry a stable nodeId instead of tripping
197	   * the registration.ts:221 "nodeId is required" guard.
198	   */
199	  rootNodeId: string;
200	}
201	
202	export interface TestContext extends TestAccount {
203	  /** Destroy the client and zero key material */
204	  cleanup: () => void;
205	}
206	
207	export interface CreateAccountOptions {
208	  apiUrl?: string;
209	  secret?: string;
210	  label: string;
211	  emailPrefix?: string;
212	  /**
213	   * Opt-in: wire this account's CipherBoxClient with a `rotationCallbacks` seam
214	   * that mirrors apps/web (rotation-driver + owner-reconcile) but sourced from
215	   * THIS account's own API via `testFetch` + its `accessToken` (never the
216	   * api-client global singleton — that carries no per-account auth). When false
217	   * (default) no `rotationCallbacks` is passed and the client behaves exactly as
218	   * every other suite's client (zero rotation). Used to prove the web
219	   * file-share grant re-mint on scope-exit rotation (recipient-pin-lifecycle §5).
220	   */
221	  withInlineGrantRemint?: boolean;
222	}
223	
224	/**
225	 * Create a test account with an initialized vault and CipherBoxClient.
226	 * This is the shared core used by both sdk-e2e (createTestContext) and
227	 * load tests (createPoolClient).
228	 */
229	export async function createTestAccount(opts: CreateAccountOptions): Promise<TestAccount> {
230	  const apiUrl = opts.apiUrl ?? API_URL;
231	  const secret = opts.secret ?? SECRET;
232	  const prefix = opts.emailPrefix ?? 'sdk-e2e';
233	  const email = `${prefix}-${opts.label}-${Date.now()}@example.com`;
234	
235	  // 1. Authenticate
236	  const loginRes = await fetch(`${apiUrl}/auth/test-login`, {
237	    method: 'POST',
238	    headers: fetchHeaders({ 'Content-Type': 'application/json' }),
239	    body: JSON.stringify({ email, secret }),
240	  });
241	  if (!loginRes.ok) {
242	    throw new Error(`test-login failed (${loginRes.status}): ${await loginRes.text()}`);
243	  }
244	  const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
245	  const publicKey = hexToBytes(publicKeyHex);
246	  const privateKey = hexToBytes(privateKeyHex);
247	
248	  // Steps 2-5 wrapped in try/catch to clean up the test account on failure
249	  try {
250	    // 2. Initialize vault
251	    const vault = await initializeVault(privateKey);
252	
253	    // 3. Publish vault key blob to IPNS (rootFolderKey storage for recovery)
254	    const axiosInstance = createAxiosInstance({
255	      baseUrl: apiUrl,
256	      getAccessToken: async () => accessToken,
257	      defaultHeaders: axiosDefaultHeaders(),
258	    });
259	    const sdkCtx: SdkContext = {
260	      apiUrl,
261	      getAccessToken: async () => accessToken,
262	      axiosInstance,
263	    };
264	    await publishVaultKeyBlob({
265	      userPrivateKey: privateKey,
266	      userPublicKey: publicKey,
267	      rootReadKey: vault.rootReadKey,
268	      rootWriteKey: vault.rootWriteKey,
269	      ctx: sdkCtx,
270	    });
271	
272	    // 4. Publish a real, empty kind:'root' Node (D-06) mirroring the web
273	    // new-user flow (useAuth.ts -> publishEmptyRootNode). Derives+returns
274	    // rootIpnsName internally -- no separate deriveIpnsName call needed
275	    // (matches decision 68.1-03). No teeKeys: the harness has no TEE
276	    // enrollment, same as a brand-new user.
277	    const {
278	      ipnsName: rootIpnsName,
279	      nodeId: rootNodeId,
280	      sequenceNumber: rootSequenceNumber,
281	    } = await publishEmptyRootNode({
282	      rootIpnsKeypair: vault.rootIpnsKeypair,
283	      rootReadKey: vault.rootReadKey,
284	      rootWriteKey: vault.rootWriteKey,
285	      ctx: sdkCtx,
286	    });
287	
288	    // 5. Register vault on server (v2: only ownerPublicKey + rootIpnsName, crypto lives in IPFS)
289	    const initRes = await fetch(`${apiUrl}/vault/init`, {
290	      method: 'POST',
291	      headers: fetchHeaders({
292	        Authorization: `Bearer ${accessToken}`,
293	        'Content-Type': 'application/json',
294	      }),
295	      body: JSON.stringify({
296	        ownerPublicKey: bytesToHex(publicKey),
297	        rootIpnsName,
298	      }),
299	    });
300	    if (!initRes.ok) {
301	      throw new Error(`vault/init failed (${initRes.status}): ${await initRes.text()}`);
302	    }
303	
304	    // 6a. Opt-in rotation seam (recipient-pin-lifecycle §5): build the
305	    // web-mirroring rotationCallbacks BEFORE constructing the client (the
306	    // callbacks close over a late-bound clientHolder, assigned after
307	    // construction). The RED test hook `E2E_DISABLE_INLINE_REMINT=1` strips the
308	    // inline seam to prove it is a real gate; every other callback stays wired so
309	    // scope-exit rotation still triggers (getActiveGrantRootIpnsNames), matching
310	    // the pre-fix sweep-only web behavior.
311	    const clientHolder: { client: CipherBoxClient | null } = { client: null };
312	    let rotationCallbacks: RotationClientCallbacks | undefined;
313	    if (opts.withInlineGrantRemint) {
314	      rotationCallbacks = buildInlineGrantRemintCallbacks(apiUrl, accessToken, clientHolder);
315	      if (process.env.E2E_DISABLE_INLINE_REMINT === '1') {
316	        rotationCallbacks.resolveInlineGrantRemint = undefined;
317	      }
318	    }
319	
320	    // 6. Create CipherBoxClient with instance-scoped axios (no singleton needed).
321	    // rootWriteKey + rootIpnsKeypair mirror the web host-layer wiring (68.1-03,
322	    // useAuth.ts) so ensureFolderLoaded / recoverWriteKeyIfNeeded can
323	    // self-bootstrap write-capable folder state from root (DFS descent).
324	    // The constructor makes defensive copies of all key buffers (D-09).
325	    const client = new CipherBoxClient({
326	      apiUrl,
327	      getAccessToken: async () => accessToken,
328	      vaultKeypair: { publicKey, privateKey },
329	      rootIpnsName,
330	      rootFolderKey: vault.rootReadKey,
331	      rootWriteKey: vault.rootWriteKey,
332	      rootIpnsKeypair: vault.rootIpnsKeypair,
333	      defaultHeaders: axiosDefaultHeaders(),
334	      ...(rotationCallbacks ? { rotationCallbacks } : {}),
335	    });
336	    // Late-bind the client into the holder so the rotationCallbacks (which only
337	    // fire during later mutations) can reach getRecipientPubkeyPins.
338	    clientHolder.client = client;
339	    // D-06: thread the published root Node's nodeId/nodeGeneration (0, first
