76	/** A sent-share row (SentShareResponseDto) from GET /shares/sent. */
77	interface SentShareRow {
78	  shareId: string;
79	  recipientPublicKey: string;
80	  encryptedReadKey: string;
81	  rootNodeId: string;
82	  shareRootIpnsName: string;
83	  rootGeneration: string;
84	}
