1	import { useState, useCallback, useEffect, useRef } from 'react';
2	import type { SealedChildRef } from '@cipherbox/core';
3	import { Modal } from '../ui/Modal';
4	import {
5	  sharesControllerRevokeShare,
6	  sharesControllerCreateShare,
7	  sharesControllerGetSentShares,
8	  sharesControllerUpdateGrant,
9	} from '@cipherbox/api-client';
10	import { wrapKey, hexToBytes, bytesToHex, bytesToBase64 } from '@cipherbox/crypto';
11	import { assertRecipientPinned } from '@cipherbox/sdk';
12	import { useShareStore } from '../../stores/share.store';
13	import type { SentShare } from '../../stores/share.store';
14	import { resolveChildNodeIdentity } from '../../lib/crypto/key-wrapping';
15	import { resolveParentIpnsName } from '../../services/invite.service';
16	import { parseRootGeneration } from '../../services/share.service';
17	import { getSdkClient } from '../../lib/sdk-provider';
18	import { InviteLinkTab } from './InviteLinkTab';
19	import '../../styles/share-dialog.css';
20	import { logger } from '../../lib/logger';
21	
22	type ShareDialogProps = {
23	  isOpen: boolean;
24	  onClose: () => void;
25	  /** The item to share (node/v3 SealedChildRef). */
26	  item: SealedChildRef;
27	  /** Real resolved kind of the shared item (79-06); gates the folder slash suffix. */
28	  kind: 'file' | 'folder';
29	  folderKey: Uint8Array;
30	  ipnsName: string;
31	  parentFolderId: string;
32	};
33	
34	/**
35	 * Truncate a public key for display: 0x{first4}...{last4}
36	 */
37	function truncateKey(key: string): string {
38	  if (key.length < 12) return key;
39	  const hex = key.startsWith('0x') ? key.slice(2) : key;
40	  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
41	}
42	
43	/**
44	 * Share dialog modal for creating and managing shares.
45	 *
46	 * Allows users to:
47	 * - Paste a recipient's public key and create a share
48	 * - View existing recipients with truncated pubkeys
49	 * - Revoke individual recipients with inline confirm
50	 *
51	 * For folders, traverses all descendants and re-wraps keys.
52	 * For files, wraps the single file key for the recipient.
53	 */
54	export function ShareDialog({
55	  isOpen,
56	  onClose,
57	  item,
58	  kind,
59	  folderKey,
60	  ipnsName,
61	  parentFolderId,
62	}: ShareDialogProps) {
63	  const [activeTab, setActiveTab] = useState<'direct' | 'invite'>('direct');
64	  const [pubKeyInput, setPubKeyInput] = useState('');
65	  const [error, setError] = useState<string | null>(null);
66	  const [success, setSuccess] = useState<string | null>(null);
67	  const [isSharing, setIsSharing] = useState(false);
68	  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);
69	  const [recipients, setRecipients] = useState<SentShare[]>([]);
70	  const [recipientsLoading, setRecipientsLoading] = useState(false);
71	  const [recipientsFetched, setRecipientsFetched] = useState(false);
72	  const [permission, setPermission] = useState<'read' | 'write'>('read');
73	  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
74	  const [revokingId, setRevokingId] = useState<string | null>(null);
75	  const [confirmDowngradeId, setConfirmDowngradeId] = useState<string | null>(null);
76	  const [upgradingId, setUpgradingId] = useState<string | null>(null);
77	  const [downgradingId, setDowngradingId] = useState<string | null>(null);
78	
79	  const inputRef = useRef<HTMLInputElement>(null);
80	  const directTabRef = useRef<HTMLButtonElement>(null);
81	  const inviteTabRef = useRef<HTMLButtonElement>(null);
82	
83	  // Fetch existing recipients when dialog opens
84	  useEffect(() => {
85	    if (!isOpen) {
86	      // Reset state on close
87	      setActiveTab('direct');
88	      setPubKeyInput('');
89	      setError(null);
90	      setSuccess(null);
91	      setIsSharing(false);
92	      setProgress(null);
93	      setPermission('read');
94	      setConfirmRevokeId(null);
95	      setRevokingId(null);
96	      setConfirmDowngradeId(null);
97	      setUpgradingId(null);
98	      setDowngradingId(null);
99	      setRecipients([]);
100	      setRecipientsLoading(false);
101	      setRecipientsFetched(false);
102	      return;
103	    }
104	
105	    let cancelled = false;
106	    setRecipientsLoading(true);
107	
108	    (async () => {
109	      // The API has no server-side ipnsName filter on /shares/sent -- page
110	      // through the full sent-share list and filter client-side to this item.
111	      // This intentionally does NOT call share.service.ts's fetchAllSentShares
112	      // + toSentShare: those fetch/map the FULL unfiltered list with
113	      // itemName '' and a `!= null` permission check, whereas this dialog
114	      // needs the filtered-to-this-item subset with itemName seeded from the
115	      // local `item.name` and the stricter truthy permission check below
116	      // (2026-07-03 todo -- divergence confirmed, not swapped to preserve
117	      // exact behavior).
118	      const pageSize = 100;
119	      let offset = 0;
120	      const matches: SentShare[] = [];
121	      let hasMore = true;
122	      while (hasMore) {
123	        const result = await sharesControllerGetSentShares({ limit: pageSize, offset });
124	        for (const s of result.shares) {
125	          if (s.shareRootIpnsName !== ipnsName) continue;
126	          matches.push({
127	            shareId: s.shareId,
128	            recipientPublicKey: s.recipientPublicKey,
129	            ipnsName: s.shareRootIpnsName,
130	            itemName: item.name,
131	            itemNameEncrypted: s.itemNameEncrypted,
132	            // Fail-closed: only a present, non-empty encryptedWriteKey grants
133	            // write. `!== null` alone would mis-map an absent (undefined) ref to
134	            // 'write'; a truthy check treats null/undefined/empty as read.
135	            permission: s.encryptedWriteKey ? 'write' : 'read',
136	            createdAt: s.createdAt,
137	            encryptedReadKey: s.encryptedReadKey,
138	            rootGeneration: parseRootGeneration(s.rootGeneration),
139	            rootNodeId: s.rootNodeId,
140	          });
141	        }
142	        offset += result.shares.length;
143	        hasMore = offset < result.total && result.shares.length > 0;
144	      }
145	      if (!cancelled) setRecipients(matches);
146	    })()
147	      .catch((err) => {
148	        if (cancelled) return;
149	        logger.error('[Share] Failed to fetch sent shares:', err);
150	      })
151	      .finally(() => {
152	        if (!cancelled) {
153	          setRecipientsLoading(false);
154	          setRecipientsFetched(true);
155	        }
156	      });
157	
158	    return () => {
159	      cancelled = true;
160	    };
161	  }, [isOpen, ipnsName, item.name]);
162	
163	  const handleShare = useCallback(async () => {
164	    setError(null);
165	    setSuccess(null);
166	
167	    const trimmed = pubKeyInput.trim();
168	    if (!trimmed) return;
169	
170	    setIsSharing(true);
171	
172	    let recipientPublicKey: Uint8Array | null = null;
173	    let itemReadKey: Uint8Array | null = null;
174	
175	    try {
176	      const hex = trimmed.startsWith('0x') ? trimmed.slice(2) : trimmed;
177	      if (!/^04[0-9a-fA-F]{128}$/.test(hex)) {
178	        throw new Error('invalid public key format');
179	      }
180	      recipientPublicKey = hexToBytes(hex);
181	
182	      const identity = await resolveChildNodeIdentity(item, folderKey);
183	      itemReadKey = identity.readKey;
184	
185	      const encryptedReadKey = bytesToHex(await wrapKey(itemReadKey, recipientPublicKey));
186	
187	      // Write grants: resolve the item's OWN writeKey from the owned
188	      // write-chain (parent writeKey -> WriteChildRef.writeKeySealed) and
189	      // ECIES-wrap it for the recipient (68.1-18, SHARE-WRITE-KEY). Raw
190	      // writeKey material never leaves the SDK -- resolveShareEncryptedWriteKey
191	      // returns only the wrapped hex encrypted key and zeroes its own derived
192	      // key internally (D-09).
193	      let encryptedWriteKey: string | undefined;
194	      if (permission === 'write') {
195	        const parentIpnsName = resolveParentIpnsName(parentFolderId);
196	        encryptedWriteKey = await getSdkClient().resolveShareEncryptedWriteKey(
197	          parentIpnsName,
198	          item.ipnsName,
199	          recipientPublicKey
200	        );
201	      }
202	
203	      let itemNameEncrypted: string | undefined;
204	      try {
205	        const nameBytes = new TextEncoder().encode(item.name);
206	        itemNameEncrypted = bytesToHex(await wrapKey(nameBytes, recipientPublicKey));
207	      } catch (err) {
208	        logger.warn('[Share] Failed to wrap item name, continuing without it:', err);
209	      }
210	
211	      // D-03c issuance write (pin-FIRST for atomicity, FOLDER shares only):
212	      // commit the pasted recipient pubkey to the shared node's owner-sealed
213	      // write-body pin list BEFORE creating the server grant. Ordering is
214	      // load-bearing — a partial failure must never strand a server grant with no
215	      // owner-sealed pin, or the D-03d fail-closed checks would permanently block
216	      // re-mint/upgrade for the whole share root (a revocation-liveness foot-gun).
217	      // Pin-first inverts the failure mode: if the grant create below fails, at
218	      // most a HARMLESS orphan pin remains — a pin grants nothing without a
219	      // matching server grant, and the append is idempotent on retry. This is
220	      // where the pin is FIRST written, so the issuance wraps above (:184/:205)
221	      // stay exempt from a pin compare; later re-mint/upgrade paths (D-03d) verify
222	      // the server-fed recipient against this pin. A failure here throws into the
223	      // shared catch below (surfaced to the user) rather than creating an
224	      // un-pinnable grant.
225	      //
226	      // FOLDERS only: addRecipientPubkeyPin reseals the shared node's OWN folder
227	      // write-body via requireFolder, so a FILE item (a leaf child, not a
228	      // folder-tree entry) would throw "not loaded" and block the share entirely.
229	      // File-share recipient pinning is not yet wired (tracked in the
230	      // recipient-pin-lifecycle todo); skip the pin for files and create the grant
231	      // as before, preserving file sharing without regressing the folder path.
232	      if (kind === 'folder') {
233	        await getSdkClient().addRecipientPubkeyPin(item.ipnsName, recipientPublicKey);
234	      }
235	
236	      const result = await sharesControllerCreateShare({
237	        recipientPublicKey: trimmed.startsWith('0x') ? trimmed : `0x${trimmed}`,
238	        encryptedReadKey,
239	        encryptedWriteKey,
240	        rootNodeId: identity.nodeId,
241	        shareRootIpnsName: item.ipnsName,
242	        rootGeneration: String(identity.generation),
243	        itemNameEncrypted,
244	      });
245	
246	      const newShare: SentShare = {
247	        shareId: result.shareId,
248	        recipientPublicKey: result.recipientPublicKey,
249	        ipnsName: item.ipnsName,
250	        itemName: item.name,
251	        itemNameEncrypted: result.itemNameEncrypted,
252	        // Fail-closed: treat absent/null/empty encryptedWriteKey as read.
253	        permission: result.encryptedWriteKey ? 'write' : 'read',
254	        createdAt: result.createdAt,
255	        encryptedReadKey: result.encryptedReadKey,
256	        rootGeneration: parseRootGeneration(result.rootGeneration),
257	        rootNodeId: result.rootNodeId,
258	      };
259	      setRecipients((prev) => [...prev, newShare]);
260	      useShareStore.getState().addSentShare(newShare);
261	      setPubKeyInput('');
262	      // Include the truncated recipient key — pre-v2.0 message contract that
263	      // sharing-workflow.spec.ts asserts on (68.1-22).
264	      setSuccess(
265	        permission === 'write'
266	          ? `> shared (read-write) with ${truncateKey(result.recipientPublicKey)}`
267	          : `> shared with ${truncateKey(result.recipientPublicKey)}`
268	      );
269	    } catch (err) {
270	      logger.error('[Share] Share creation failed:', err);
271	      // Surface the API's error body (NestJS { message } shape) instead of
272	      // the raw axios "Request failed with status code NNN" text (68.1-29);
273	      // lowercased to match the dialog's terminal-style copy.
274	      const responseMessage = (err as { response?: { data?: { message?: string | string[] } } })
275	        .response?.data?.message;
276	      const apiMessage = Array.isArray(responseMessage) ? responseMessage[0] : responseMessage;
277	      const message =
278	        apiMessage?.toLowerCase() ?? (err instanceof Error ? err.message : 'share failed');
279	      setError(`> ${message}`);
280	    } finally {
281	      setIsSharing(false);
282	      itemReadKey?.fill(0);
283	    }
284	  }, [pubKeyInput, item, folderKey, permission, parentFolderId, kind]);
285	
286	  const handleRevoke = useCallback(async (shareId: string) => {
287	    setRevokingId(shareId);
288	    setConfirmRevokeId(null);
289	    try {
290	      await sharesControllerRevokeShare(shareId);
291	      setRecipients((prev) => prev.filter((r) => r.shareId !== shareId));
292	      useShareStore.getState().removeSentShare(shareId);
293	    } catch (err) {
294	      logger.error('[Share] Revoke failed:', err);
295	      setError('revoke failed');
296	    } finally {
297	      setRevokingId(null);
298	    }
299	  }, []);
300	
301	  const handleUpgrade = useCallback(
302	    async (share: SentShare) => {
303	      setError(null);
304	      setSuccess(null);
305	      // Fail-closed (V5): never PATCH with a coerced generation. An undefined
306	      // rootGeneration means the DTO carried no valid generation — refuse the
307	      // upgrade rather than send a stale "0".
308	      if (share.rootGeneration === undefined) {
309	        setError('> cannot upgrade: share is stale, please reload');
310	        return;
311	      }
312	      setUpgradingId(share.shareId);
313	
314	      let recipientPublicKey: Uint8Array | null = null;
315	
316	      try {
317	        // Upgrading read -> write mints the shared item's own writeKey from
318	        // the owned write-chain (parent writeKey -> WriteChildRef.writeKeySealed,
319	        // 68.1-18's resolveShareEncryptedWriteKey) and PATCHes the SAME share row
320	        // (no revoke/recreate, same shareId) via updateGrant -- the
321	        // encryptedReadKey/rootGeneration are re-sent unchanged so this call
322	        // only ever advances the write side.
323	        const bareHex = share.recipientPublicKey.startsWith('0x')
324	          ? share.recipientPublicKey.slice(2)
325	          : share.recipientPublicKey;
326	        recipientPublicKey = hexToBytes(bareHex);
327	
328	        // D-03d consumer 3 (fail-closed): the recipientPublicKey above comes
329	        // from the server-fed sent-share store and MUST NOT be trusted for the
330	        // re-wrap. Verify it against the node's owner-sealed recipientPins
331	        // (D-03c issuance write) BEFORE re-wrapping. `getRecipientPubkeyPins`
332	        // returns raw pubkey bytes; normalize to base64 for the shared sdk-core
333	        // helper (its stored-pin encoding). A mismatch or absent/empty pin list
334	        // throws — aborting the upgrade before resolveShareEncryptedWriteKey
335	        // (D-03e no-legacy hard fail); the compare is NOT reimplemented here.
336	        //
337	        // FOLDERS only (symmetric with the issuance gate at :232): the pin READER
338	        // `getRecipientPubkeyPins` -> requireFolder resolves the shared node's OWN
339	        // folder write-body, so a FILE item (a leaf child, not a folder-tree entry)
340	        // would throw "not loaded" and block the upgrade entirely (greptile P1).
341	        // File-share recipient pinning is not yet wired (tracked in the
342	        // recipient-pin-lifecycle todo), so a file share carries no owner-sealed
343	        // pin to verify against; skip the pin enforce for files, mirroring the
344	        // write path, rather than fail-closing an unpinnable file upgrade.
345	        if (kind === 'folder') {
346	          const pins = await getSdkClient().getRecipientPubkeyPins(item.ipnsName);
347	          assertRecipientPinned(recipientPublicKey, pins.map(bytesToBase64));
348	        }
349	
350	        const parentIpnsName = resolveParentIpnsName(parentFolderId);
351	        const encryptedWriteKey = await getSdkClient().resolveShareEncryptedWriteKey(
352	          parentIpnsName,
353	          item.ipnsName,
354	          recipientPublicKey
355	        );
356	
357	        await sharesControllerUpdateGrant(share.shareId, {
358	          encryptedReadKey: share.encryptedReadKey,
359	          rootGeneration: String(share.rootGeneration),
360	          encryptedWriteKey,
361	        });
362	
363	        setRecipients((prev) =>
364	          prev.map((r) => (r.shareId === share.shareId ? { ...r, permission: 'write' } : r))
365	        );
366	        useShareStore.getState().updateSentSharePermission(share.shareId, 'write');
367	        setSuccess('> upgraded to read-write');
368	      } catch (err) {
369	        logger.error('[Share] Permission upgrade failed:', err);
370	        setError('> permission upgrade failed, please try again');
371	      } finally {
372	        setUpgradingId(null);
373	        // recipientPublicKey is public key material (not sensitive), but
374	        // clear the transient buffer reference regardless (D-09 discipline).
375	        recipientPublicKey?.fill(0);
376	      }
377	    },
378	    [item, parentFolderId, kind]
379	  );
380	
381	  const handleDowngradeConfirm = useCallback(async (share: SentShare) => {
382	    setError(null);
383	    setSuccess(null);
384	    // Fail-closed (V5): refuse to downgrade with a coerced generation.
385	    if (share.rootGeneration === undefined) {
386	      setError('> cannot downgrade: share is stale, please reload');
387	      return;
388	    }
389	    setDowngradingId(share.shareId);
390	    setConfirmDowngradeId(null);
391	
392	    try {
393	      // Downgrading write -> read clears the share's encryptedWriteKey via
394	      // the explicit clearEncryptedWriteKey signal (68.1-19) -- the read side
395	      // (encryptedReadKey/rootGeneration) is re-sent unchanged, same shareId.
396	      await sharesControllerUpdateGrant(share.shareId, {
397	        encryptedReadKey: share.encryptedReadKey,
398	        rootGeneration: String(share.rootGeneration),
399	        clearEncryptedWriteKey: true,
400	      });
401	
402	      // Update local state
403	      setRecipients((prev) =>
404	        prev.map((r) => (r.shareId === share.shareId ? { ...r, permission: 'read' } : r))
405	      );
406	      useShareStore.getState().updateSentSharePermission(share.shareId, 'read');
407	      setSuccess('> downgraded to read-only');
408	    } catch (err) {
409	      logger.error('[Share] Permission downgrade failed:', err);
410	      setError('> permission change failed, please try again');
411	    } finally {
412	      setDowngradingId(null);
413	    }
414	  }, []);
415	
416	  const handleKeyDown = useCallback(
417	    (e: React.KeyboardEvent) => {
418	      if (e.key === 'Enter' && !isSharing) {
419	        handleShare();
420	      }
421	    },
422	    [handleShare, isSharing]
423	  );
424	
425	  // Folders get a trailing-slash display suffix; files show the bare name.
426	  const itemDisplayName = kind === 'folder' ? `${item.name}/` : item.name;
427	  const title = `SHARE: ${itemDisplayName}`;
428	
429	  return (
430	    <Modal open={isOpen} onClose={onClose} title={title} className="share-dialog-backdrop">
431	      <div className="share-dialog">
432	        {/* Tab bar */}
433	        <div className="share-tab-bar" role="tablist" aria-label="Share method">
434	          <button
435	            ref={directTabRef}
436	            type="button"
437	            role="tab"
438	            id="share-tab-direct"
439	            aria-selected={activeTab === 'direct'}
440	            aria-controls="share-panel-direct"
